Q: How to Create Adaptive Card With Positioned Text/Buttons in Flutter? A: <pre class="lang-dart prettyprint-override"><code>
class GroupCardScreen extends StatelessWidget {
  const GroupCardScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFF7E3A3A),
      body: Center(
        child: Padding(padding: const EdgeInsets.all(16), child: GroupCard()),
      ),
    );
  }
}

class GroupCard extends StatelessWidget {
  const GroupCard({super.key});

  @override
  Widget build(BuildContext context) {
    return AspectRatio(
      aspectRatio: 1.85,
      child: ClipRRect(
        borderRadius: BorderRadius.circular(32),
        child: Stack(
          children: [
            /// Background Image
            Positioned.fill(
              child: Image.network(
                &quot;https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe&quot;,
                fit: BoxFit.cover,
              ),
            ),

            /// Dark Overlay
            Positioned.fill(
              child: Container(color: Colors.black.withOpacity(0.25)),
            ),

            /// Content
            Positioned.fill(
              child: Padding(
                padding: const EdgeInsets.all(22),
                child: Align(
                  alignment: Alignment.bottomRight,
                  child: Stack(
                    clipBehavior: .none,
                    children: [
                      Positioned(child: _buildActivityCard()),

                      Positioned(
                        bottom:10,
                        right:-10,
                        child: Container(
                          width: 40,
                          height: 40,
                          decoration: BoxDecoration(
                            shape: BoxShape.circle,
                            color: Colors.black.withOpacity(.25),
                            border: Border.all(color: Colors.white24),
                          ),
                          child: const Icon(
                            Icons.arrow_forward_ios_rounded,
                            color: Colors.white,
                            size: 25,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ),
            Positioned(
              bottom: 10,
              left: 20,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Text(
                    &quot;5 members&quot;,
                    style: TextStyle(color: Colors.white, fontSize: 18),
                  ),

                  const SizedBox(height: 8),

                  SizedBox(
                    height: 42,
                    width: 150,
                    child: Stack(
                      children: List.generate(
                        5,
                        (index) =&gt; Positioned(
                          left: index * 18,
                          child: Container(
                            width: 28,
                            height: 28,
                            decoration: BoxDecoration(
                              shape: BoxShape.circle,
                              color: Colors.white,
                              border: Border.all(color: Colors.black, width: 2),
                            ),
                            child: const Icon(
                              Icons.person,
                              size: 18,
                              color: Colors.black,
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                ],
              ),
            ),
            Positioned(
              left: 12,
              top: 20,
              width: MediaQuery.of(context).size.width * 0.9,
              child: Padding(
                padding: const EdgeInsets.all(8.0),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    const Text(
                      &quot;Group Name&quot;,
                      style: TextStyle(
                        color: Colors.white,
                        fontSize: 25,
                        fontWeight: FontWeight.w400,
                      ),
                    ),

                    Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 26,
                        vertical: 10,
                      ),
                      decoration: BoxDecoration(
                        color: const Color(0xFF547C16),
                        borderRadius: BorderRadius.circular(24),
                      ),
                      child: const Text(
                        &quot;Planned&quot;,
                        style: TextStyle(color: Colors.white, fontSize: 18),
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  static Widget _buildActivityCard() {
    return ClipRRect(
      borderRadius: BorderRadius.circular(24),
      child: BackdropFilter(
        filter: ImageFilter.blur(sigmaX: 12, sigmaY: 12),
        child: Container(
          width: 220,
          height: 160,
          padding: const EdgeInsets.all(18),
          decoration: BoxDecoration(
            color: Colors.black.withOpacity(.20),
            borderRadius: BorderRadius.circular(24),
            border: Border.all(color: Colors.white.withOpacity(.15)),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: const [
                  Icon(
                    Icons.movie_creation_outlined,
                    color: Colors.white,
                    size: 20,
                  ),
                  SizedBox(width: 10),
                  Text(
                    &quot;Last Activity&quot;,
                    style: TextStyle(color: Colors.white, fontSize: 18),
                  ),
                ],
              ),

              SizedBox(height: 12),

              Row(
                children: const [
                  Icon(
                    Icons.check_circle_outline,
                    color: Colors.white,
                    size: 18,
                  ),
                  SizedBox(width: 8),
                  Text(
                    &quot;Confirmed&quot;,
                    style: TextStyle(color: Colors.white, fontSize: 16),
                  ),
                ],
              ),

              SizedBox(height: 8),

              Text(
                &quot;Fri, June 10&quot;,
                style: TextStyle(color: Colors.white, fontSize: 17),
              ),

              SizedBox(height: 2),

              Text(
                &quot;20:00&quot;,
                style: TextStyle(
                  color: Color(0xFF76B82A),
                  fontSize: 18,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}
</code></pre>
